script:
export const meta = {
  name: 'e2e-demo-workflow',
  description: 'E2E demo: two phases, multiple spawned agents',
  phases: [
    { title: 'Gather', detail: 'two gather agents' },
    { title: 'Summarize', detail: 'one summarizer' },
  ],
}
const S = { type: 'object', properties: { word: { type: 'string' } }, required: ['word'], additionalProperties: false }
phase('Gather')
log('gather phase')
const g = await parallel([1,2].map(i => () =>
  agent(`Return the single word "gather${i}". Nothing else.`, {label: `gather-${i}`, phase: 'Gather', schema: S})))
phase('Summarize')
log('summarize phase')
const s = await agent(`Return the single word "summary". Nothing else.`, {label: 'summarizer', phase: 'Summarize', schema: S})
return { gathered: g, summary: s }
